      out.write("<script>\n");
      out.write("// ======================================================================\n");
      out.write("//  ECharts 仪表板 — 支持多数据集切换\n");
      out.write("// ======================================================================\n");
      out.write("var currentDs = 0;\n");
      out.write("// Read ds from URL param\n");
      out.write("var urlParams = new URLSearchParams(window.location.search);\n");
      out.write("if (urlParams.has('ds')) currentDs = parseInt(urlParams.get('ds'));\n");
      out.write("\n");
      out.write("// Load available datasets into dropdown\n");
      out.write("fetch('/movie-analysis/api/data?type=datasets')\n");
      out.write("    .then(r => r.json())\n");
      out.write("    .then(function(data) {\n");
      out.write("        var sel = document.getElementById('dsSelector');\n");
      out.write("        sel.innerHTML = '';\n");
      out.write("        data.forEach(function(d) {\n");
      out.write("            sel.innerHTML += '<option value=\"' + d.id + '\" style=\"color:#333;\"' +\n");
      out.write("                (d.id == currentDs ? ' selected' : '') + '>' +\n");
      out.write("                d.name + ' (' + d.rating_count + ' ratings)</option>';\n");
      out.write("            // Update header with current dataset name\n");
      out.write("            if (d.id == currentDs) {\n");
      out.write("                document.getElementById('headerDs').textContent = d.name;\n");
      out.write("            }\n");
      out.write("        });\n");
      out.write("        // Fallback: if currentDs not found, use first\n");
      out.write("        if (currentDs == 0 || currentDs == 1) {\n");
      out.write("            document.getElementById('headerDs').textContent = data[0] ? data[0].name : 'MovieLens 1M';\n");
      out.write("        }\n");
      out.write("    });\n");
      out.write("\n");
      out.write("function switchDataset(dsId) {\n");
      out.write("    window.location.href = '/movie-analysis/?ds=' + dsId;\n");
      out.write("}\n");
      out.write("\n");
      out.write("// ==================== 通用工具 ====================\n");
      out.write("function formatCount(n) {\n");
      out.write("    n = parseInt(n);\n");
      out.write("    if (n >= 10000) return (n / 10000).toFixed(1) + '万';\n");
      out.write("    if (n >= 1000) return (n / 1000).toFixed(1) + 'k';\n");
      out.write("    return n.toLocaleString();\n");
      out.write("}\n");
      out.write("function fetchData(type, callback) {\n");
      out.write("    fetch('/movie-analysis/api/data?type=' + type + '&ds=' + currentDs)\n");
      out.write("        .then(res => res.json())\n");
      out.write("        .then(data => callback(data))\n");
      out.write("        .catch(err => console.error(type + ': ' + err));\n");
      out.write("}\n");
      out.write("\n");
      out.write("function initChart(domId) {\n");
      out.write("    return echarts.init(document.getElementById(domId));\n");
      out.write("}\n");
      out.write("\n");
      out.write("// ==================== 0. 仪表板汇总统计 ====================\n");
      out.write("// 数据源: /api/data?type=summary → dashboard_summary 表\n");
      out.write("// 更新: 4 个 stat-card (电影总数/评分总数/用户总数/综合平均分)\n");
      out.write("fetchData('summary', function(data) {\n");
      out.write("    if (data.length > 0) {\n");
      out.write("        var s = data[0];\n");
      out.write("        document.querySelectorAll('#statsRow .stat-card')[0].querySelector('.value').textContent\n");
      out.write("            = parseInt(s.total_movies).toLocaleString();\n");
      out.write("        document.querySelectorAll('#statsRow .stat-card')[1].querySelector('.value').textContent\n");
      out.write("            = formatCount(s.total_ratings);\n");
      out.write("        document.querySelectorAll('#statsRow .stat-card')[2].querySelector('.value').textContent\n");
      out.write("            = parseInt(s.total_users);\n");
      out.write("        document.querySelectorAll('#statsRow .stat-card')[3].querySelector('.value').textContent\n");
      out.write("            = parseFloat(s.avg_rating).toFixed(2);\n");
      out.write("    }\n");
      out.write("});\n");
      out.write("\n");
      out.write("// ==================== 1. 评分分布柱状图 ====================\n");
      out.write("// 数据源: /api/data?type=rating_dist → rating_distribution 表\n");
      out.write("// 图表: x轴=1~5分, y轴=评分数量, 渐变柱状图 + 平均值标线\n");
      out.write("fetchData('rating_dist', function(data) {\n");
      out.write("    var chart = initChart('chartRatingDist');\n");
      out.write("    var scores = data.map(d => d.score + '分');\n");
      out.write("    var counts = data.map(d => parseInt(d.count));\n");
      out.write("    chart.setOption({\n");
      out.write("        tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' } },\n");
      out.write("        xAxis: { type: 'category', data: scores, name: '评分' },\n");
      out.write("        yAxis: { type: 'value', name: '数量',\n");
      out.write("            axisLabel: { formatter: v => v >= 10000 ? (v/10000).toFixed(0) + 'w' : v } },\n");
      out.write("        series: [{\n");
      out.write("            type: 'bar', data: counts,\n");
      out.write("            itemStyle: { color: new echarts.graphic.LinearGradient(0,0,0,1,[\n");
      out.write("                {offset:0, color:'#667eea'}, {offset:1, color:'#764ba2'}\n");
      out.write("            ])},\n");
      out.write("            markLine: { \n");
      out.write("                data: [{ type: 'average', name: '平均值' }],\n");
      out.write("                label: { position: 'insideEndTop', fontSize: 11 }\n");
      out.write("            }\n");
      out.write("        }],\n");
      out.write("        grid: { left: 65, right: 35, top: 35, bottom: 35, containLabel: true }\n");
      out.write("    });\n");
      out.write("});\n");
      out.write("\n");
      out.write("// ==================== 2. 热门电影 TOP20 水平条形图 ====================\n");
      out.write("// 数据源: /api/data?type=top_movies → top_movies 表\n");
      out.write("// 图表: y轴=电影名, x轴=平均评分, 水平渐变条形图 + 右侧数值标签\n");
      out.write("fetchData('top_movies', function(data) {\n");
      out.write("    var chart = initChart('chartTopMovies');\n");
      out.write("    var movies = data.map(d => d.movie_name).reverse();\n");
      out.write("    var ratings = data.map(d => parseFloat(d.avg_rating)).reverse();\n");
      out.write("    var counts = data.map(d => d.rating_count).reverse();\n");
      out.write("    var minR = Math.max(0, (Math.min.apply(null, ratings) - 0.5).toFixed(1));\n");
      out.write("    var maxR = (Math.max.apply(null, ratings) + 0.3).toFixed(1);\n");
      out.write("    chart.setOption({\n");
      out.write("        tooltip: {\n");
      out.write("            trigger: 'axis',\n");
      out.write("            formatter: function(params) {\n");
      out.write("                var i = params[0].dataIndex;\n");
      out.write("                return movies[i] + '<br/>平均分: ' + ratings[i] + '<br/>评分人数: ' + counts[i];\n");
      out.write("            }\n");
      out.write("        },\n");
      out.write("        xAxis: { type: 'value', name: '平均评分', nameLocation: 'center', nameGap: 25,\n");
      out.write("            min: minR, max: maxR },\n");
      out.write("        yAxis: { type: 'category', data: movies,\n");
      out.write("            axisLabel: { fontSize: 11,\n");
      out.write("                formatter: function(v) { return v.length > 25 ? v.substring(0,23) + '...' : v; }\n");
      out.write("            }\n");
      out.write("        },\n");
      out.write("        series: [{\n");
      out.write("            type: 'bar', data: ratings,\n");
      out.write("            itemStyle: { color: new echarts.graphic.LinearGradient(0,0,1,0,[\n");
      out.write("                {offset:0, color:'#43e97b'}, {offset:1, color:'#38f9d7'}\n");
      out.write("            ])},\n");
      out.write("            label: { show: true, position: 'right', fontSize: 10, formatter: '{c}' }\n");
      out.write("        }],\n");
      out.write("        grid: { left: 5, right: 60, top: 5, bottom: 30, containLabel: true }\n");
      out.write("    });\n");
      out.write("});\n");
      out.write("\n");
      out.write("// ==================== 3. 电影类别分布玫瑰饼图 ====================\n");
      out.write("// 数据源: /api/data?type=genre_stats → genre_stats 表 (取前10)\n");
      out.write("// 图表: ECharts 玫瑰饼图 (roseType:area), 显示各类别电影数量占比\n");
      out.write("fetchData('genre_stats', function(data) {\n");
      out.write("    var chart = initChart('chartGenreDist');\n");
      out.write("    var top10 = data.slice(0, 10);\n");
      out.write("    chart.setOption({\n");
      out.write("        tooltip: {\n");
      out.write("            trigger: 'item',\n");
      out.write("            formatter: '{b}: {c} 部 ({d}%)'\n");
      out.write("        },\n");
      out.write("        series: [{\n");
      out.write("            type: 'pie',\n");
      out.write("            radius: ['45%', '75%'],\n");
      out.write("            center: ['50%', '55%'],\n");
      out.write("            roseType: 'area',\n");
      out.write("            itemStyle: { borderRadius: 4 },\n");
      out.write("            data: top10.map(d => ({ name: d.genre_name, value: parseInt(d.movie_count) })),\n");
      out.write("            label: { fontSize: 10 },\n");
      out.write("            emphasis: {\n");
      out.write("                itemStyle: { shadowBlur: 10, shadowOffsetX: 0, shadowColor: 'rgba(0,0,0,0.3)' }\n");
      out.write("            }\n");
      out.write("        }]\n");
      out.write("    });\n");
      out.write("});\n");
      out.write("\n");
      out.write("// ==================== 4. 男女用户评分对比组合图 ====================\n");
      out.write("// 数据源: /api/data?type=gender_comp → gender_comparison 表\n");
      out.write("// 图表: 双柱(用户数+评分量) + 双线(均分+好评率), 双Y轴\n");
      out.write("fetchData('gender_comp', function(data) {\n");
      out.write("    var chart = initChart('chartGenderComp');\n");
      out.write("    chart.setOption({\n");
      out.write("        tooltip: { trigger: 'axis' },\n");
      out.write("        legend: { data: ['用户数', '评分量(万)', '平均评分', '好评率(%)'] },\n");
      out.write("        xAxis: { type: 'category', data: data.map(d => d.gender) },\n");
      out.write("        yAxis: [\n");
      out.write("            { type: 'value', name: '数量' },\n");
      out.write("            { type: 'value', name: '评分/百分比' }\n");
      out.write("        ],\n");
      out.write("        series: [\n");
      out.write("            { name: '用户数', type: 'bar', data: data.map(d => parseInt(d.user_count)),\n");
      out.write("                itemStyle: { color: '#5470c6' } },\n");
      out.write("            { name: '评分量', type: 'bar', data: data.map(d => parseInt(d.rating_count)),\n");
      out.write("                itemStyle: { color: '#91cc75' } },\n");
      out.write("            { name: '平均评分', type: 'line', yAxisIndex: 1,\n");
      out.write("                data: data.map(d => parseFloat(d.avg_rating)),\n");
      out.write("                itemStyle: { color: '#ee6666' } },\n");
      out.write("            { name: '好评率(%)', type: 'line', yAxisIndex: 1,\n");
      out.write("                data: data.map(d => parseFloat(d.high_rate_pct)),\n");
      out.write("                itemStyle: { color: '#fac858' } }\n");
      out.write("        ],\n");
      out.write("        grid: { left: 60, right: 60, top: 40, bottom: 30, containLabel: true }\n");
